contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    function test(address newDistributor) external {
        // Precondition: the caller of this test is not the owner of c,
        // so any setRewardDistributor attempt from here must fail on P.
        require(c.owner() != address(this), "caller must not be owner");

        // Attempt to change the reward distributor from a non-owner address.
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.setRewardDistributor.selector, newDistributor)
        );

        // On P the call reverts (onlyOwner guard). On M the mutant the call
        // succeeds and hands distributor control to an arbitrary address.
        assert(!ok);
    }
}

